import{_ as t,c as a,o,ag as r}from"./chunks/framework.DPDPlp3K.js";const h=JSON.parse('{"title":"Features","description":"","frontmatter":{"title":"Features","order":2},"headers":[],"relativePath":"docs/features/index.md","filePath":"en/docs/features/index.md"}'),i={name:"docs/features/index.md"};function n(d,e,s,u,c,l){return o(),a("div",null,e[0]||(e[0]=[r('<h1 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h1><h2 id="site-modes" tabindex="-1">Site Modes <a class="header-anchor" href="#site-modes" aria-label="Permalink to &quot;Site Modes&quot;">​</a></h2><p>The core capability of Pavonis is expressed through <strong>site modes</strong>. A single instance can run any number of sites simultaneously, each choosing a mode that covers container images, code hosting, ML platforms, package management and more:</p><table tabindex="0"><thead><tr><th>Mode</th><th>Purpose</th></tr></thead><tbody><tr><td><code>gh_proxy</code></td><td>GitHub Releases, Raw files, Gist acceleration</td></tr><tr><td><code>container_registry_single</code></td><td>Proxy a specific OCI container registry (e.g. Docker Hub, GHCR)</td></tr><tr><td><code>container_registry_any</code></td><td>Universal container image proxy, routing by hostname embedded in the request path</td></tr><tr><td><code>http</code></td><td>General HTTP reverse proxy with path-based routing</td></tr><tr><td><code>pypi</code></td><td>PyPI index mirror, rewrites download links automatically</td></tr><tr><td><code>hugging_face</code></td><td>HuggingFace model and dataset download proxy</td></tr><tr><td><code>speed_test</code></td><td>Upload/download speed test endpoints</td></tr></tbody></table><p>→ <a href="./../sites/">Site Modes Documentation</a></p><h2 id="outbound-ip-pool" tabindex="-1">Outbound IP Pool <a class="header-anchor" href="#outbound-ip-pool" aria-label="Permalink to &quot;Outbound IP Pool&quot;">​</a></h2><p>When your server holds a large IPv6 address block (e.g. a <code>/48</code> subnet from HE Tunnel Broker), you can enable the IP pool to let Pavonis select outbound IPs from the pool at random or by rule, effectively bypassing per-IP rate limits imposed by upstream platforms. Supports <code>random</code> and <code>ip_hash</code> (pinned by client IP) strategies, with per-site override support.</p><p>→ <a href="./ip-pool">IP Pool Documentation</a></p><h2 id="traffic-and-request-rate-limiting" tabindex="-1">Traffic and Request Rate Limiting <a class="header-anchor" href="#traffic-and-request-rate-limiting" aria-label="Permalink to &quot;Traffic and Request Rate Limiting&quot;">​</a></h2><p>Control outbound bandwidth using a token bucket algorithm. Simultaneously supports per-second, per-minute and per-hour request count limits to prevent the proxy from consuming excessive resources or being abused. Both rate limits are optional — leave them unset to impose no limit.</p><p>→ <a href="./rate-limiting">Rate Limiting Documentation</a></p><h2 id="authentication-headers-and-outbound-proxy" tabindex="-1">Authentication, Headers and Outbound Proxy <a class="header-anchor" href="#authentication-headers-and-outbound-proxy" aria-label="Permalink to &quot;Authentication, Headers and Outbound Proxy&quot;">​</a></h2><p>Container registry sites support client authentication with built-in hot-reload of user files (no restart required to update the user list). Automatically strips reverse-proxy-related headers to prevent leaking proxy chain information to upstreams. A single outbound proxy can be configured for all upstream requests.</p><p>→ <a href="./auth-and-headers">Auth, Headers and Outbound Proxy Documentation</a></p>',14)]))}const m=t(i,[["render",n]]);export{h as __pageData,m as default};
